import{_ as o,o as t,c as a,a3 as s}from"./chunks/framework.8k0sTANV.js";const m=JSON.parse('{"title":"Storybook MCP","description":"","frontmatter":{},"headers":[],"relativePath":"docs/agents/storybook-mcp.md","filePath":"docs/agents/storybook-mcp.md"}'),r={name:"docs/agents/storybook-mcp.md"};function n(i,e,d,c,h,l){return t(),a("div",null,[...e[0]||(e[0]=[s('<h1 id="storybook-mcp" tabindex="-1">Storybook MCP <a class="header-anchor" href="#storybook-mcp" aria-label="Permalink to &quot;Storybook MCP&quot;">​</a></h1><p>The component workshop (<a href="./../adr/0028-storybook-is-the-component-workshop-of-the-design-system">ADR 0028</a>) serves an MCP server through <code>@storybook/addon-mcp</code>, declared in <code>.mcp.json</code> as <code>storybook</code> (<code>http://localhost:6006/mcp</code>). It lets an agent check what the design system already has while it builds a web screen, instead of drawing a simpler control of its own.</p><h2 id="use-it" tabindex="-1">Use it <a class="header-anchor" href="#use-it" aria-label="Permalink to &quot;Use it&quot;">​</a></h2><ol><li>Start the workshop: <code>cd web &amp;&amp; npm ci &amp;&amp; npm run storybook</code>. The server only exists while it runs; with it stopped, the tools are unavailable and the stories can be read in <code>web/storybook/stories/</code>.</li><li>Before writing or changing a web component or screen, call <code>get-storybook-story-instructions</code>, then <code>stories-find-by-component</code> to find the stories that render the component you touch. Reuse an existing <code>Cp*</code> component; a missing one is added to <code>web/ui</code> (<a href="./areas">areas</a>), never drawn in the app.</li><li>After a change that alters how the UI looks, call <code>test-run</code> for the stories you touched and <code>stories-preview</code> to look at them. A new state is a new story with a <code>play</code> function.</li></ol><h2 id="what-it-does-not-do" tabindex="-1">What it does not do <a class="header-anchor" href="#what-it-does-not-do" aria-label="Permalink to &quot;What it does not do&quot;">​</a></h2><ul><li>It does not judge visual quality. The agreed mockup is the contract (see <a href="./../../CLAUDE">CLAUDE.md</a>): compare the screen with it, light and dark.</li><li>It sees the Vue components of <code>web/ui</code> only, not the Android and iOS screens.</li><li>It is young: if a tool misbehaves, fall back to reading the stories and <code>npm test -w storybook</code>, and note the problem in the PR.</li></ul>',6)])])}const u=o(r,[["render",n]]);export{m as __pageData,u as default};
